#!/usr/bin/env python3
"""Rebuilds src/assets/mdi/: Material Design Icons cut down to the icons the
source uses. The full font is 394 KB (woff2) for ~7,000 glyphs; the app uses a
few hundred. Run it after adding an icon (tests/mdiSubset.test.js fails until
you do):

    pip install fonttools brotli
    python3 scripts/subset-mdi.py

Icon names are literals in the source (`mdi-sword`); the font comes from the
@mdi/font dev dependency, so `npm ci` first."""
import re
import subprocess
import sys
from pathlib import Path

root = Path(__file__).resolve().parent.parent
font_dir = root / "node_modules" / "@mdi" / "font"
out_dir = root / "src" / "assets" / "mdi"

css = (font_dir / "css" / "materialdesignicons.css").read_text()
# Not anchored to a line start: the stylesheet's last rules follow its source-map comment.
glyph_rule = re.compile(r'\.mdi-([a-z0-9-]+)::before \{\n  content: "\\([0-9A-F]+)";\n\}\n\n?')
glyphs = {name: code for name, code in glyph_rule.findall(css)}

# What the app asks for: every mdi-* token in the source.
tokens = set()
for path in (root / "src").rglob("*"):
    if path.suffix in {".vue", ".js", ".css"} and out_dir not in path.parents:
        tokens |= set(re.findall(r"\bmdi-[a-z0-9]+(?:-[a-z0-9]+)*", path.read_text()))
used = sorted(t[4:] for t in tokens if t[4:] in glyphs)

# The rest of the stylesheet (the .mdi base class, sizes, flips, spin): kept as is.
rest = glyph_rule.sub("", css)
rest = re.sub(r"/\*# sourceMappingURL=.*?\*/", "", rest)
rest = re.sub(r"@font-face \{.*?\n\}\n\n?", "", rest, flags=re.S).lstrip("\n")

subset_css = (
    "/* Generated by scripts/subset-mdi.py from @mdi/font: do not edit. */\n"
    '@font-face {\n  font-family: "Material Design Icons";\n'
    '  src: url("./materialdesignicons-subset.woff2") format("woff2");\n'
    "  font-weight: normal;\n  font-style: normal;\n}\n\n"
    + rest
    + "".join(f'.mdi-{n}::before {{\n  content: "\\{glyphs[n]}";\n}}\n\n' for n in used)
)
(out_dir / "materialdesignicons-subset.css").write_text(subset_css.rstrip() + "\n")

unicodes = ",".join(f"U+{glyphs[n]}" for n in used)
subprocess.run(
    ["pyftsubset", str(font_dir / "fonts" / "materialdesignicons-webfont.woff2"),
     f"--unicodes={unicodes}", "--flavor=woff2", "--no-hinting", "--layout-features=",
     "--glyph-names", f"--output-file={out_dir / 'materialdesignicons-subset.woff2'}"],
    check=True,
)
size = (out_dir / "materialdesignicons-subset.woff2").stat().st_size
print(f"{len(used)} icons, {size / 1024:.1f} KB", file=sys.stderr)
